def rep(t, old, new, cnt=1):
    assert t.count(old) == cnt, (old[:70], t.count(old))
    return t.replace(old, new)


def sect(t, head, nxt, new):
    i = t.index("\n" + head) + 1
    j = t.index("\n" + nxt, i) + 1
    return t[:i] + new.rstrip("\n") + "\n\n" + t[j:]


